import { describe, expect, it } from "vitest";
import { ALL_TOOL_CONTRACTS, saveTraceAssertions, searchTraces, TOOL_NAMES, toolConfig, } from "./mcpContract.js";
describe("tool contracts", () => {
    it("registers 46 tools with unique names", () => {
        expect(ALL_TOOL_CONTRACTS).toHaveLength(46);
        expect(new Set(TOOL_NAMES).size).toBe(46);
        expect(TOOL_NAMES.join(" ")).not.toMatch(/trace_plan/);
        expect(TOOL_NAMES).not.toContain("create_trace_plan");
        expect(TOOL_NAMES).not.toContain("update_trace_plan");
    });
    it("names every tool in snake_case", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            expect(contract.name, contract.name).toMatch(/^[a-z][a-z0-9]*(_[a-z0-9]+)*$/);
        }
    });
    it("gives every tool a title and a description", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            expect(contract.title.length, contract.name).toBeGreaterThan(0);
            expect(contract.description.length, contract.name).toBeGreaterThan(0);
        }
    });
    it("names every input parameter in camelCase", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            for (const param of Object.keys(contract.inputSchema)) {
                expect(param, `${contract.name}.${param}`).toMatch(/^[a-z][a-zA-Z0-9]*$/);
            }
        }
    });
    it("describes every input parameter", () => {
        for (const contract of ALL_TOOL_CONTRACTS) {
            for (const [param, schema] of Object.entries(contract.inputSchema)) {
                expect(schema.description, `${contract.name}.${param} has no .describe()`).toBeTruthy();
            }
        }
    });
    it("drops the name from the registerTool config", () => {
        const config = toolConfig(ALL_TOOL_CONTRACTS[0]);
        expect(config).not.toHaveProperty("name");
        expect(Object.keys(config).sort()).toEqual([
            "description",
            "inputSchema",
            "title",
        ]);
    });
    it("lets MCP callers write people-only notes on assertions", () => {
        const parsed = saveTraceAssertions.inputSchema.assertions.safeParse([
            {
                assertion: "The itinerary lands before 9am",
                humanNote: "Preserve this for the human reviewer",
            },
        ]);
        expect(parsed.success).toBe(true);
        expect(saveTraceAssertions.description).toMatch(/never use it to judge/);
    });
    it("normalizes caller metadata filters for case-insensitive search", () => {
        expect(searchTraces.inputSchema.callerMetadata.parse({ Ticket_ID: "ABC-123" })).toEqual({ ticket_id: "abc-123" });
    });
    it("normalizes name filters for case-insensitive search", () => {
        expect(searchTraces.inputSchema.name.parse("  Nightly Checkout ")).toBe("nightly checkout");
        expect(searchTraces.inputSchema.nameContains.parse(" CHECKOUT ")).toBe("checkout");
    });
    it("refuses a name substring too short to use the trigram index", () => {
        expect(searchTraces.inputSchema.nameContains.safeParse("ab").success).toBe(false);
    });
});
